import { FcGoogle } from 'react-icons/fc';
import { FaFacebook } from 'react-icons/fa';

const SocialLoginButtons = ({ onGoogleLogin, onFacebookLogin, action = 'login' }) => {
  const getActionText = (provider) => {
    if (action === 'login') {
      return provider === 'google' ? 'Continuer avec Google' : 'Continuer avec Facebook';
    } else {
      return provider === 'google' ? 'S\'inscrire avec Google' : 'S\'inscrire avec Facebook';
    }
  };

  return (
    <div className="space-y-3">
      {/* Bouton Google */}
      <button
        type="button"
        onClick={onGoogleLogin}
        className="w-full flex items-center justify-center gap-3 px-4 py-3.5 border border-gray-300 rounded-xl hover:bg-gray-50 transition-all duration-300 hover:shadow-md hover:border-gray-400 active:scale-[0.99] group"
      >
        <div className="relative">
          <FcGoogle className="text-xl" />
          <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-10 rounded-full transition-opacity" />
        </div>
        <span className="font-semibold text-gray-700 group-hover:text-gray-900 transition-colors">
          {getActionText('google')}
        </span>
      </button>

      {/* Bouton Facebook */}
      <button
        type="button"
        onClick={onFacebookLogin}
        className="w-full flex items-center justify-center gap-3 px-4 py-3.5 border border-blue-100 rounded-xl bg-blue-50 hover:bg-blue-100 transition-all duration-300 hover:shadow-md hover:border-blue-200 active:scale-[0.99] group"
      >
        <div className="relative">
          <FaFacebook className="text-xl text-blue-600" />
          <div className="absolute inset-0 bg-blue-600 opacity-0 group-hover:opacity-10 rounded-full transition-opacity" />
        </div>
        <span className="font-semibold text-blue-700 group-hover:text-blue-900 transition-colors">
          {getActionText('facebook')}
        </span>
      </button>

      {/* Note de sécurité */}
      <p className="text-xs text-center text-gray-500 pt-2">
        Vos informations sont sécurisées avec {action === 'login' ? 'la connexion' : 'l\'inscription'} sociale
      </p>
    </div>
  );
};

export default SocialLoginButtons;
